/// Every kind this Jadpo writes.
pub const KINDS: &[&Kind] = &[
    &API,
    &EVENTS,
    &ACCESS,
    &NETWORK,
    &SURFACE,
    &IDENTITIES,
    &TRANSLATIONS,
    &IGNORED_SUGGESTIONS,
    &TAUGHT_SUGGESTIONS,
    &LOCK,
];

/// The extension of every record but the lock.
pub const EXTENSION: &str = ".jadpo_record";

/// The kind of the record at a project-relative path, and what its header
/// says it was generated from.
pub fn kind_of(path: &str) -> Option<(&'static Kind, String)> {
    let parts: Vec<&str> = path.split('/').collect();
    match parts.as_slice() {
        ["api", file] => {
            let api = file.strip_suffix(EXTENSION).filter(|api| !api.is_empty())?;
            Some((&API, format!("the routes of API {api}")))
        }
        ["domains", domain, "events", file] if *file == EVENTS_FILE && !domain.is_empty() => {
            Some((&EVENTS, format!("the events of domain {domain}")))
        }
        ["database", "identities.jadpo_record"] => Some((&IDENTITIES, "renames and moves".into())),
        [file] if *file == ACCESS_FILE => Some((&ACCESS, ACCESS_FROM.into())),
        [file] if *file == NETWORK_FILE => Some((&NETWORK, NETWORK_FROM.into())),
        ["domains", _, "translations", "sources.jadpo_record"]
        | ["shared", "translations", "sources.jadpo_record"]
        | ["translations", "sources.jadpo_record"] => {
            Some((&TRANSLATIONS, "this folder's translations".into()))
        }
        ["ignored_suggestions.jadpo_record"] => Some((
            &IGNORED_SUGGESTIONS,
            "the suggestions this project ignores".into(),
        )),
        ["taught_suggestions.jadpo_record"] => Some((
            &TAUGHT_SUGGESTIONS,
            "the patterns this project taught `jadpo suggest`".into(),
        )),
        ["jadpo.lock"] => Some((&LOCK, "the installed packages".into())),
        [.., file]
            if *file == SURFACE_FILE
                && crate::places::package_at(path)
                    .is_some_and(|(_, rest)| rest.as_slice() == [SURFACE_FILE]) =>
        {
            Some((&SURFACE, SURFACE_FROM.into()))
        }
        _ => None,
    }
}

/// A record kept under the name it had before chunk 7.0, and the path it
/// has now: `api/<api>.api` and `database/identities.json`.
pub fn renamed(path: &str) -> Option<String> {
    match path.split('/').collect::<Vec<_>>().as_slice() {
        ["api", file] => {
            let api = file.strip_suffix(".api").filter(|api| !api.is_empty())?;
            Some(format!("api/{api}{EXTENSION}"))
        }
        ["database", "identities.json"] => Some(crate::IDENTITIES.to_string()),
        _ => None,
    }
}

/// The header's first line: what the record was generated from and what
/// updates it.
pub fn header_line(kind: &Kind, from: &str) -> String {
    format!(
        "// Generated by Jadpo from {from}; update it with {}, never by hand.",
        kind.update
    )
}

/// Both header lines, each ending in a newline.
pub fn header(kind: &Kind, from: &str) -> String {
    format!(
        "{}\nrecord {} {}\n",
        header_line(kind, from),
        kind.word,
        kind.format
    )
}

/// What is wrong with a record's first two lines.
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum HeaderProblem {
    /// The file is empty.
    Empty,
    /// Line 1 isn't the header this record is written with.
    Comment,
    /// Line 2 isn't `record <kind> <format>`.
    RecordLine,
    /// Line 2 names another kind.
    OtherKind(String),
    /// Written by a newer Jadpo, in this format.
    Newer(u32),
    /// A view written by an older Jadpo, in this format: out of date.
    Older(u32),
}

impl HeaderProblem {
    /// The line it is on, from 0.
    pub fn line(&self) -> usize {
        match self {
            HeaderProblem::Empty | HeaderProblem::Comment => 0,
            _ => 1,
        }
    }

    /// What is wrong, in a few words.
    pub fn describe(&self, kind: &Kind) -> String {
        match self {
            HeaderProblem::Empty => "the file is empty".into(),
            HeaderProblem::Comment => "the first line is not the header Jadpo writes".into(),
            HeaderProblem::RecordLine => format!(
                "the second line is not `record {} {}`",
                kind.word, kind.format
            ),
            HeaderProblem::OtherKind(word) => {
                format!(
                    "it says it is a `{word}` record, not a `{}` record",
                    kind.word
                )
            }
            HeaderProblem::Newer(format) => format!(
                "it is in format {format} of the `{}` record, and this Jadpo writes format {}",
                kind.word, kind.format
            ),
            HeaderProblem::Older(format) => format!(
                "it is in format {format} of the `{}` record, and this Jadpo writes format {}",
                kind.word, kind.format
            ),
        }
    }
}

/// The text with Windows line endings read as LF, as every record is
/// compared.
pub fn normalise(text: &str) -> std::borrow::Cow<'_, str> {
    if text.contains('\r') {
        std::borrow::Cow::Owned(text.replace("\r\n", "\n"))
    } else {
        std::borrow::Cow::Borrowed(text)
    }
}

/// The format a record's header says it is in, once both lines are the
/// ones this Jadpo writes for `kind` from `from`, or for one of its older
/// ledger formats.
pub fn read_header(text: &str, kind: &Kind, from: &str) -> Result<u32, HeaderProblem> {
    let mut lines = text.lines();
    let Some(first) = lines.next() else {
        return Err(HeaderProblem::Empty);
    };
    let second = lines.next().unwrap_or("");
    let words: Vec<&str> = second.split(' ').collect();
    let format = match words.as_slice() {
        ["record", word, number] => {
            let format: u32 = number
                .parse()
                .ok()
                .filter(|_| !number.starts_with('0') || *number == "0")
                .ok_or(HeaderProblem::RecordLine)?;
            if *word != kind.word {
                return Err(HeaderProblem::OtherKind(word.to_string()));
            }
            format
        }
        _ if first == header_line(kind, from) || first.starts_with("// ") => {
            return Err(HeaderProblem::RecordLine);
        }
        _ => return Err(HeaderProblem::Comment),
    };
    if format > kind.format {
        return Err(HeaderProblem::Newer(format));
    }
    if format == kind.format {
        if first != header_line(kind, from) {
            return Err(HeaderProblem::Comment);
        }
        return Ok(format);
    }
    match kind.older.iter().find(|(older, _)| *older == format) {
        Some((_, line)) if first == *line => Ok(format),
        Some(_) => Err(HeaderProblem::Comment),
        None if kind.shape == Shape::View => Err(HeaderProblem::Older(format)),
        None => Err(HeaderProblem::RecordLine),
    }
}

/// One entry: a heading in column 0 and its members.
#[derive(Clone, Debug, Default, PartialEq, Eq)]
pub struct Entry {
    pub heading: String,
    pub members: Vec<Member>,
}

/// A member of an entry, indented four spaces, and the fields that belong
/// to it, indented eight (an enum variant's fields).
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Member {
    pub line: String,
    pub nested: Vec<String>,
}

impl Entry {
    pub fn new(heading: impl Into<String>) -> Entry {
        Entry {
            heading: heading.into(),
            members: Vec::new(),
        }
    }

    /// Adds a member line.
    pub fn push(&mut self, line: impl Into<String>) {
        self.members.push(Member {
            line: line.into(),
            nested: Vec::new(),
        });
    }

    /// Adds a field to the last member.
    pub fn push_nested(&mut self, line: impl Into<String>) {
        if let Some(member) = self.members.last_mut() {
            member.nested.push(line.into());
        }
    }

    /// The entry with a member added.
    pub fn with(mut self, line: impl Into<String>) -> Entry {
        self.push(line);
        self
    }

    /// The entry as the record writes it, members and all.
    pub fn text(&self) -> String {
        let mut out = format!("{}\n", self.heading);
        for member in &self.members {
            out.push_str(&format!("    {}\n", member.line));
            for nested in &member.nested {
                out.push_str(&format!("        {nested}\n"));
            }
        }
        out
    }
}

/// The record for `entries`, under the header for `kind` from `from`: one
/// blank line after the header and between entries that have members,
/// none between one-line entries.
pub fn write(kind: &Kind, from: &str, entries: &[Entry]) -> String {
    let mut out = header(kind, from);
    let mut previous: Option<&Entry> = None;
    for entry in entries {
        let joined = previous
            .is_some_and(|previous| previous.members.is_empty() && entry.members.is_empty());
        if !joined {
            out.push('\n');
        }
        out.push_str(&entry.text());
        previous = Some(entry);
    }
    out
}

/// What is wrong with a line of a record: the line, from 0, and why.
pub type LineProblem = (usize, String);

/// A record's entries, after its two header lines, or the first line that
/// isn't one Jadpo writes for `kind`: a comment, a tab, a trailing space,
/// an indent that isn't four or eight spaces, a heading or fact outside
/// the kind's closed list, or blank lines where none belong.
pub fn read(text: &str, kind: &Kind) -> Result<Vec<Entry>, LineProblem> {
    let mut entries: Vec<Entry> = Vec::new();
    for (at, line) in text.lines().enumerate().skip(2) {
        if line.contains('\t') {
            return Err((at, "the line has a tab".into()));
        }
        if line.ends_with(' ') {
            return Err((at, "the line ends in a space".into()));
        }
        if line.is_empty() {
            continue;
        }
        if line.starts_with("//") && !line.trim_start().starts_with("///") {
            return Err((at, "a comment isn't part of a record".into()));
        }
        let indent = line.len() - line.trim_start_matches(' ').len();
        let content = &line[indent..];
        if !content.starts_with("///") && has_comment(content) {
            return Err((at, "a comment isn't part of a record".into()));
        }
        match indent {
            0 => {
                let word = content.split(' ').next().unwrap_or("");
                let known = if kind.headings.is_empty() {
                    is_word(word)
                } else {
                    kind.headings.contains(&word)
                };
                if !known {
                    return Err((
                        at,
                        format!("`{word}` doesn't start an entry of this record"),
                    ));
                }
                entries.push(Entry::new(content));
            }
            4 => {
                let Some(entry) = entries.last_mut() else {
                    return Err((at, "an indented line comes before any entry".into()));
                };
                if kind.shape == Shape::History {
                    return Err((at, "this record's entries are one line each".into()));
                }
                if !is_member(content, kind) {
                    let word = content.split(' ').next().unwrap_or("");
                    return Err((at, format!("`{word}` isn't a fact of this record")));
                }
                entry.push(content);
            }
            8 => {
                let Some(member) = entries
                    .last_mut()
                    .and_then(|entry| entry.members.last_mut())
                else {
                    return Err((at, "a field comes before what it belongs to".into()));
                };
                if field_name(content).is_none() {
                    return Err((at, "only a field is indented eight spaces".into()));
                }
                member.nested.push(content.to_string());
            }
            _ => return Err((at, format!("the line is indented {indent} spaces"))),
        }
    }
    Ok(entries)
}

/// Whether a record's text is exactly what Jadpo writes for its entries:
/// header, layout and blank lines. The first line that differs if not.
pub fn canonical(text: &str, kind: &Kind, from: &str) -> Result<Vec<Entry>, LineProblem> {
    let entries = read(text, kind)?;
    let written = write(kind, from, &entries);
    if written == text {
        return Ok(entries);
    }
    let at = written
        .lines()
        .zip(text.lines())
        .position(|(a, b)| a != b)
        .unwrap_or_else(|| written.lines().count().min(text.lines().count()));
    let why = if text.lines().nth(at).is_some_and(str::is_empty) {
        "a blank line Jadpo doesn't write"
    } else if !text.ends_with('\n') {
        "the file doesn't end in a newline"
    } else {
        "the layout differs from what Jadpo writes"
    };
    Err((at, why.to_string()))
}

/// Whether a line holds ` //` outside a string: a comment added by hand.
/// A URL's `://` isn't one.
fn has_comment(line: &str) -> bool {
    let mut in_string = false;
    let mut escaped = false;
    let bytes = line.as_bytes();
    for (at, byte) in bytes.iter().enumerate() {
        match byte {
            _ if escaped => escaped = false,
            b'\\' if in_string => escaped = true,
            b'"' => in_string = !in_string,
            b'/' if !in_string
                && bytes.get(at + 1) == Some(&b'/')
                && (at == 0 || bytes[at - 1] == b' ') =>
            {
                return true;
            }
            _ => {}
        }
    }
    false
}

fn is_word(word: &str) -> bool {
    !word.is_empty()
        && word
            .bytes()
            .all(|b| b.is_ascii_lowercase() || b.is_ascii_digit() || b == b'_')
}

/// The name of a field line, `name: value`.
fn field_name(line: &str) -> Option<&str> {
    let (name, rest) = line.split_once(':')?;
    (is_word(name) && rest.starts_with(' ')).then_some(name)
}

fn is_member(line: &str, kind: &Kind) -> bool {
    if line == "///" || line.starts_with("/// ") || field_name(line).is_some() {
        return true;
    }
    let word = line.split(' ').next().unwrap_or("");
    kind.facts.contains(&word)
}

/// `text` as a Jadpo string, with only Jadpo's escapes: `\"`, `\\`, `\n`,
/// `\r` and `\t`.
pub fn quote(text: &str) -> String {
    let mut out = String::from('"');
    for c in text.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            other => out.push(other),
        }
    }
    out.push('"');
    out
}

/// How an entry differs between two versions of a record.
#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord)]
pub enum Change {
    Added,
    Changed,
    Removed,
}

impl Change {
    pub fn word(self) -> &'static str {
        match self {
            Change::Added => "added",
            Change::Changed => "changed",
            Change::Removed => "removed",
        }
    }
}

/// The entries added, changed and removed from `before` to `after`, each
/// known by its heading, in `after`'s order then the removed ones in
/// `before`'s. A failure's heading is its code alone, so its status and
/// message changing reads as a change, not a removal and an addition.
pub fn changes(before: &[Entry], after: &[Entry]) -> Vec<(Change, String)> {
    let index = |entries: &[Entry]| -> BTreeMap<String, String> {
        entries
            .iter()
            .map(|entry| (entry.heading.clone(), entry.text()))
            .collect()
    };
    let old = index(before);
    let new = index(after);
    let mut out = Vec::new();
    for entry in after {
        match old.get(&entry.heading) {
            None => out.push((Change::Added, entry.heading.clone())),
            Some(text) if *text != entry.text() => {
                out.push((Change::Changed, entry.heading.clone()));
            }
            Some(_) => {}
        }
    }
    for entry in before {
        if !new.contains_key(&entry.heading) {
            out.push((Change::Removed, entry.heading.clone()));
        }
    }
    out
}

#[cfg(test)]
mod tests {
    use super::*;

    const FROM: &str = "the routes of API main";

    fn todos() -> Vec<Entry> {
        vec![
            Entry::new("api main").with("idempotency required"),
            Entry::new("POST /todos")
                .with("authentication none")
                .with("input CreateTodo (body)")
                .with("output TodoView")
                .with("status 201"),
            Entry::new("output TodoView")
                .with("id: Uuid")
                .with("title: Text { min_length: 1, max_length: 200 }"),
        ]
    }

    #[test]
    fn the_header_says_what_wrote_it_and_the_command_that_updates_it() {
        assert_eq!(
            header(&API, FROM),
            "// Generated by Jadpo from the routes of API main; update it with `jadpo api update`, never by hand.\nrecord api 1\n"
        );
        assert_eq!(
            header_line(&LOCK, "the installed packages"),
            "// Generated by Jadpo from the installed packages; update it with `jadpo package add`, `update` or `remove`, never by hand."
        );
    }

    #[test]
    fn a_view_reads_back_what_it_wrote() {
        let text = write(&API, FROM, &todos());
        assert_eq!(
            text,
            "// Generated by Jadpo from the routes of API main; update it with `jadpo api update`, never by hand.
record api 1

api main
    idempotency required

POST /todos
    authentication none
    input CreateTodo (body)
    output TodoView
    status 201

output TodoView
    id: Uuid
    title: Text { min_length: 1, max_length: 200 }
"
        );
        assert_eq!(read_header(&text, &API, FROM), Ok(1));
        assert_eq!(canonical(&text, &API, FROM), Ok(todos()));
    }

    /// A provider's callback route answers with a redirect (area 8,
    /// "Providers"), and a stale record holding it still reads, so `check`
    /// says it is out of date rather than edited by hand (chunk A6).
    #[test]
    fn a_provider_callbacks_redirect_reads_back() {
        let entries = vec![{
            let mut entry = Entry::new("GET /auth/google/callback");
            entry.push("generated provider sign-in");
            entry.push("authentication none");
            entry.push("redirect return_to");
            entry.push("status 303");
            entry
        }];
        let text = write(&API, FROM, &entries);
        assert_eq!(canonical(&text, &API, FROM), Ok(entries));
    }

    #[test]
    fn one_line_entries_have_no_blank_line_between_them() {
        let entries = vec![
            Entry::new("entity Todo -> Task"),
            Entry::new("field Todo.priority -> importance"),
        ];
        let text = write(&IDENTITIES, "renames and moves", &entries);
        assert!(text.ends_with(
            "record identities 1\n\nentity Todo -> Task\nfield Todo.priority -> importance\n"
        ));
        assert_eq!(
            canonical(&text, &IDENTITIES, "renames and moves"),
            Ok(entries)
        );
        assert_eq!(
            write(&IDENTITIES, "renames and moves", &[]).lines().count(),
            2
        );
    }

    #[test]
    fn a_hand_edit_is_found_by_its_line() {
        let text = write(&API, FROM, &todos());
        let edited = text.replace("    status 201\n", "    status 201 // was 200\n");
        assert_eq!(
            canonical(&edited, &API, FROM).map_err(|(at, _)| at),
            Err(10)
        );
        let comment = text.replace("api main\n", "// keep this\napi main\n");
        assert_eq!(
            canonical(&comment, &API, FROM),
            Err((3, "a comment isn't part of a record".into()))
        );
        let fact = text.replace("    status 201", "    code 201");
        assert_eq!(
            canonical(&fact, &API, FROM),
            Err((10, "`code` isn't a fact of this record".into()))
        );
        let tab = text.replace("    status 201", "\tstatus 201");
        assert_eq!(
            canonical(&tab, &API, FROM),
            Err((10, "the line has a tab".into()))
        );
        let blank = text.replace("POST /todos\n", "\nPOST /todos\n");
        assert_eq!(canonical(&blank, &API, FROM).map_err(|(at, _)| at), Err(6));
        let ledger = "// Generated by Jadpo from renames and moves; update it with `jadpo rename`, `jadpo domain` or `jadpo fmt --layout`, never by hand.\nrecord identities 1\n\nentity Todo -> Task\n    note: Text\n";
        assert_eq!(
            canonical(ledger, &IDENTITIES, "renames and moves"),
            Err((4, "this record's entries are one line each".into()))
        );
    }

    #[test]
    fn the_header_is_checked_line_by_line() {
        let text = write(&API, FROM, &todos());
        assert_eq!(read_header("", &API, FROM), Err(HeaderProblem::Empty));
        assert_eq!(
            read_header(
                &text.replacen("Generated by Jadpo", "Written by hand", 1),
                &API,
                FROM
            ),
            Err(HeaderProblem::Comment)
        );
        assert_eq!(
            read_header(&text.replace("record api 1", "record api 2"), &API, FROM),
            Err(HeaderProblem::Newer(2))
        );
        assert_eq!(
            read_header(&text.replace("record api 1", "record api 0"), &API, FROM),
            Err(HeaderProblem::Older(0))
        );
        assert_eq!(
            read_header(&text.replace("record api 1", "record lock 1"), &API, FROM),
            Err(HeaderProblem::OtherKind("lock".into()))
        );
        assert_eq!(
            read_header(&text.replace("record api 1", "version: 3"), &API, FROM),
            Err(HeaderProblem::RecordLine)
        );
        assert_eq!(
            read_header(&text, &API, "the routes of API admin"),
            Err(HeaderProblem::Comment)
        );
    }

    #[test]
    fn a_ledger_reads_its_older_formats() {
        let old = "// Written by `jadpo suggest ignore`; `jadpo suggest` drops entries whose code has gone. Never edit it by hand.\nrecord ignored_suggestions 1\n";
        let from = "the suggestions this project ignores";
        assert_eq!(read_header(old, &IGNORED_SUGGESTIONS, from), Ok(1));
        assert_eq!(
            read_header(
                &header(&IGNORED_SUGGESTIONS, from),
                &IGNORED_SUGGESTIONS,
                from
            ),
            Ok(2)
        );
    }

    #[test]
    fn records_are_known_by_their_paths() {
        let kind = |path: &str| kind_of(path).map(|(kind, from)| (kind.word, from));
        assert_eq!(
            kind("api/main.jadpo_record"),
            Some(("api", "the routes of API main".into()))
        );
        assert_eq!(
            kind("database/identities.jadpo_record").map(|k| k.0),
            Some("identities")
        );
        assert_eq!(
            kind("domains/shipping/translations/sources.jadpo_record").map(|k| k.0),
            Some("translations")
        );
        assert_eq!(kind("jadpo.lock").map(|k| k.0), Some("lock"));
        assert_eq!(
            kind("domains/planning/events/events.jadpo_record"),
            Some(("events", "the events of domain planning".into()))
        );
        assert_eq!(kind("domains/planning/events/todo_completed.jadpo"), None);
        assert_eq!(
            header_line(&EVENTS, "the events of domain planning"),
            "// Generated by Jadpo from the events of domain planning; update it with `jadpo records update`, never by hand."
        );
        assert_eq!(kind("api/main.api"), None);
        assert_eq!(
            renamed("api/main.api").as_deref(),
            Some("api/main.jadpo_record")
        );
        assert_eq!(
            renamed("database/identities.json").as_deref(),
            Some("database/identities.jadpo_record")
        );
    }

    #[test]
    fn entries_are_compared_by_heading() {
        let before = todos();
        let mut after = todos();
        after[1].push("fails todo_locked");
        after.remove(0);
        after.push(Entry::new("failure todo_locked").with("status 409"));
        assert_eq!(
            changes(&before, &after),
            vec![
                (Change::Changed, "POST /todos".to_string()),
                (Change::Added, "failure todo_locked".to_string()),
                (Change::Removed, "api main".to_string()),
            ]
        );
    }

    #[test]
    fn strings_use_only_jadpos_escapes() {
        assert_eq!(quote("Say \"hi\"\\\n"), "\"Say \\\"hi\\\"\\\\\\n\"");
        assert_eq!(quote("café"), "\"café\"");
    }
}
